<?php
$guardPanel=$guardPanel??'admin';if(empty($_SESSION['auth_csrf']))$_SESSION['auth_csrf']=bin2hex(random_bytes(24));
?>
<script>(()=>{let last=Date.now(),limit=<?=auth_config()['idleMinutes']?>*60000,lastPing=0,done=false;window.addEventListener('control-credentials-changed',()=>{done=true;});const logout=()=>{if(done)return;done=true;location.href=<?=json_encode(url($guardPanel.'/logout.php'))?>;};const active=()=>{if(Date.now()-last>=limit){logout();return;}last=Date.now();};for(const e of ['pointerdown','keydown','touchstart','scroll'])window.addEventListener(e,active,{passive:true});setInterval(async()=>{if(done)return;if(Date.now()-last>=limit){logout();return;}if(document.hidden||Date.now()-last>60000||Date.now()-lastPing<60000)return;lastPing=Date.now();try{const r=await fetch(<?=json_encode(url($guardPanel.'/security-api.php'))?>,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'heartbeat',csrf:<?=json_encode($_SESSION['auth_csrf'])?>})});if(r.status===401){done=true;location.href=<?=json_encode(url($guardPanel.'/login.php'))?>;}else if(r.ok){const d=await r.json();limit=d.idleMinutes*60000;}}catch{}},10000);})();</script>
